import{_ as e,o,c as d,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"模型服务商与模型","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/providers/llm.md","filePath":"zh/integrations/providers/llm.md","lastUpdated":1790952322000}'),a={name:"zh/integrations/providers/llm.md"};function i(n,t,l,c,s,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="模型服务商与模型" tabindex="-1">模型服务商与模型 <a class="header-anchor" href="#模型服务商与模型" aria-label="Permalink to &quot;模型服务商与模型&quot;">​</a></h1><p>日常用 Memoh，多半要配好：</p><ul><li>一个或多个 <strong>模型服务商</strong>（怎么连上游 API）</li><li>其下的 <strong>模型</strong></li><li>若要朗读，再配 <strong>语音合成</strong>（见 <a href="./tts/edge.html">TTS 提供方</a>）</li><li>若要把语音转文字，再配 <strong>语音转写</strong></li></ul><p>聊天与 embedding 在 <strong>Models</strong> 页管理；语音合成模型在 TTS 流程里单走，语音转写模型在 Transcription 设置页管理。</p><hr><h2 id="模型服务商基础" tabindex="-1">模型服务商基础 <a class="header-anchor" href="#模型服务商基础" aria-label="Permalink to &quot;模型服务商基础&quot;">​</a></h2><p><strong>模型服务商</strong>里存的是某一类上游的连法，例如：</p><ul><li>协议（<code>client_type</code>）</li><li>需要时的 base URL</li><li>API Key 或 OAuth 等凭据</li></ul><p>常见有 OpenAI 兼容站、Anthropic、Google、Codex、GitHub Copilot 等。</p><h3 id="新建模型服务商" tabindex="-1">新建模型服务商 <a class="header-anchor" href="#新建模型服务商" aria-label="Permalink to &quot;新建模型服务商&quot;">​</a></h3><p>模型服务商现在从<strong>模板目录</strong>建。模板自带对的 client type、base URL 和一份精选模型清单，通常你只需要填个 API Key。</p><ol><li>侧栏打开 <strong>Models</strong>。</li><li>点 <strong>Add Provider</strong>，从模板列表挑——只显示你还没配过的，可搜索（中文厂商名也能搜到）。</li><li>填模板要的凭据。</li><li>保存。模型服务商和它的预置模型在保存时一起生成。</li></ol><p>内置模板包括 OpenAI、Anthropic、Google、OpenRouter、DeepSeek、<strong>智谱 AI（bigmodel.cn）</strong>、Z.AI、Azure OpenAI、Cerebras、Cloudflare、Fireworks、Perplexity、Together 等。注意<strong>智谱 AI</strong>（<code>open.bigmodel.cn</code>，国内账号）和 <strong>Z.AI</strong>（<code>api.z.ai</code>，国际账号）是两个模板、两套 key 体系——按你的 key 是哪边发的来选。</p><p>没有合适模板时，仍可以建全自定义模型服务商。</p><p>常用字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>展示名，如 <code>OpenAI</code>。</td></tr><tr><td><strong>Client Type</strong></td><td>本模型服务商用的协议。</td></tr><tr><td><strong>Base URL</strong></td><td>部分协议必填的根地址。</td></tr><tr><td><strong>API Key</strong></td><td>走密钥时填。</td></tr></tbody></table><h3 id="客户端类型" tabindex="-1">客户端类型 <a class="header-anchor" href="#客户端类型" aria-label="Permalink to &quot;客户端类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Client Type</th><th>常见用途</th></tr></thead><tbody><tr><td><code>openai-responses</code></td><td>OpenAI Responses 风格</td></tr><tr><td><code>openai-completions</code></td><td>Chat Completions 兼容</td></tr><tr><td><code>anthropic-messages</code></td><td>Anthropic Messages</td></tr><tr><td><code>google-generative-ai</code></td><td>Google Gemini</td></tr><tr><td><code>openai-codex</code></td><td>Codex / ChatGPT 那套，OAuth</td></tr><tr><td><code>github-copilot</code></td><td>Copilot，设备码 OAuth</td></tr><tr><td><code>edge-speech</code></td><td>Edge 朗读</td></tr><tr><td><code>openai-speech</code></td><td>OpenAI 兼容语音合成</td></tr><tr><td><code>openai-transcription</code></td><td>OpenAI 兼容语音转写</td></tr><tr><td><code>openrouter-speech</code></td><td>OpenRouter 语音合成</td></tr><tr><td><code>openrouter-transcription</code></td><td>OpenRouter 语音转写</td></tr><tr><td><code>elevenlabs-speech</code></td><td>ElevenLabs 语音合成</td></tr><tr><td><code>elevenlabs-transcription</code></td><td>ElevenLabs 语音转写</td></tr><tr><td><code>deepgram-speech</code></td><td>Deepgram 语音合成</td></tr><tr><td><code>deepgram-transcription</code></td><td>Deepgram 语音转写</td></tr><tr><td><code>minimax-speech</code></td><td>MiniMax 语音合成</td></tr><tr><td><code>volcengine-speech</code></td><td>火山引擎语音合成</td></tr><tr><td><code>alibabacloud-speech</code></td><td>阿里云语音合成</td></tr><tr><td><code>microsoft-speech</code></td><td>Microsoft 语音合成</td></tr><tr><td><code>google-transcription</code></td><td>Google 语音转写</td></tr></tbody></table><p>语音合成与语音转写类型不能当主聊天用。语音合成走 <a href="./tts/edge.html">TTS 提供方</a>，语音转写走 Transcription 设置页。具体模型、音色和语言取决于 provider 模板与上游账号。</p><hr><h2 id="走-oauth-的模型服务商" tabindex="-1">走 OAuth 的模型服务商 <a class="header-anchor" href="#走-oauth-的模型服务商" aria-label="Permalink to &quot;走 OAuth 的模型服务商&quot;">​</a></h2><p>多数类型用普通 API Key。<code>openai-codex</code> 和 <code>github-copilot</code> 例外——两个都走<strong>设备码授权</strong>，同一套流程，都没有 API Key 输入框：</p><ol><li>先建好并<strong>保存</strong>模型服务商——授权入口只在已保存模型服务商的详情面板里。</li><li><strong>Account</strong> 区点 <strong>Connect</strong>，界面给出验证 URL、一次性用户码和过期倒计时。</li><li>点 <strong>Copy &amp; Open</strong>，去验证页输码，Memoh 自动完成收尾。</li></ol><blockquote><p>一次性码只在显示的官方验证 URL 上输——设备码可能被用于钓鱼。</p></blockquote><p>连上后模型服务商上会显示当前账号，<strong>Revoke</strong> 断开。</p><h3 id="openai-codex" tabindex="-1">OpenAI Codex <a class="header-anchor" href="#openai-codex" aria-label="Permalink to &quot;OpenAI Codex&quot;">​</a></h3><ul><li>类型 <code>openai-codex</code>，模板指向 <code>https://chatgpt.com/backend-api</code></li><li>用 ChatGPT 账号登录</li></ul><p>偏写代码、走 Codex 那套时合适。</p><h3 id="github-copilot" tabindex="-1">GitHub Copilot <a class="header-anchor" href="#github-copilot" aria-label="Permalink to &quot;GitHub Copilot&quot;">​</a></h3><ul><li>类型 <code>github-copilot</code></li><li>用 GitHub 账号登录</li></ul><p>你本来就有 Copilot 时，可复用进 Memoh。</p><div class="warning custom-block"><p class="custom-block-title">升级提醒</p><p>Copilot 凭据以前按用户存，现在和 Codex 一样是模型服务商级的一份。老部署升级后要把 Copilot 模型服务商<strong>重新授权一次</strong>。</p></div><h3 id="托管模型目录" tabindex="-1">托管模型目录 <a class="header-anchor" href="#托管模型目录" aria-label="Permalink to &quot;托管模型目录&quot;">​</a></h3><p>两个 OAuth 模型服务商的模型列表都是<strong>托管目录</strong>，从上游实时拉取（Codex 干脆没有静态清单，永远反映你 ChatGPT 账号实际能用什么）：</p><ul><li>设备授权完成后目录自动同步，之后也可以随时重新导入。</li><li>上游目录里消失的模型标记为不可用，不会被删。</li><li>重复导入是增量合并：补上新发现的能力，不覆盖你自己的模型配置。</li></ul><hr><h2 id="导入模型" tabindex="-1">导入模型 <a class="header-anchor" href="#导入模型" aria-label="Permalink to &quot;导入模型&quot;">​</a></h2><p>建完模型服务商后，可以在它下面导入或手动添加模型。</p><p>典型流程：</p><ol><li>选中模型服务商。</li><li>若它能给出模型目录，点 <strong>Import Models</strong>。</li><li>勾选要存进 Memoh 的模型。</li></ol><p>已知上游模型 ID 时，也可以手动添加。</p><h3 id="模型启用开关" tabindex="-1">模型启用开关 <a class="header-anchor" href="#模型启用开关" aria-label="Permalink to &quot;模型启用开关&quot;">​</a></h3><p>模型服务商详情页里每个模型一行，各带<strong>启用开关</strong>。禁用的模型仍留在这页方便再开，但会从所有模型选择器（Bot 设置、聊天、embedding 等）里消失。</p><p>默认值看模型怎么来的：</p><ul><li><strong>手动</strong>添加的模型默认启用。</li><li><strong>批量导入</strong>的模型默认<strong>禁用</strong>——导一大目录不至于把每个选择器刷爆，要用哪个自己开哪个。</li></ul><hr><h2 id="模型类型" tabindex="-1">模型类型 <a class="header-anchor" href="#模型类型" aria-label="Permalink to &quot;模型类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>用途</th></tr></thead><tbody><tr><td><code>chat</code></td><td>对话、工具、推理、文生图等</td></tr><tr><td><code>embedding</code></td><td>向量化、记忆检索</td></tr><tr><td><code>speech</code></td><td>朗读，挂在 TTS</td></tr><tr><td><code>transcription</code></td><td>语音转文字，挂在 Transcription</td></tr></tbody></table><p><strong>Models</strong> 页主要管 chat / embedding；speech 在 <a href="./tts/edge.html">TTS 提供方</a>，transcription 在 Transcription 设置页。</p><hr><h2 id="聊天模型上要注意的项" tabindex="-1">聊天模型上要注意的项 <a class="header-anchor" href="#聊天模型上要注意的项" aria-label="Permalink to &quot;聊天模型上要注意的项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Model ID</strong></td><td>上游真实 id，如 <code>gpt-4o</code>。</td></tr><tr><td><strong>Name</strong></td><td>界面展示名。</td></tr><tr><td><strong>Description</strong></td><td>可选说明文字，模型列表里悬停可见，选择器里还能按它搜。</td></tr><tr><td><strong>Compatibilities</strong></td><td>如 <code>vision</code>、<code>tool-call</code>、<code>image-output</code>、<code>reasoning</code>。</td></tr><tr><td><strong>Context Window</strong></td><td>粗算上下文上限。</td></tr></tbody></table><h3 id="兼容性" tabindex="-1">兼容性 <a class="header-anchor" href="#兼容性" aria-label="Permalink to &quot;兼容性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标记</th><th>含义</th></tr></thead><tbody><tr><td><code>vision</code></td><td>能吃图</td></tr><tr><td><code>tool-call</code></td><td>能调工具</td></tr><tr><td><code>image-output</code></td><td>能出图</td></tr><tr><td><code>reasoning</code></td><td>有显式推理/档位</td></tr></tbody></table><p>有推理时可能还带 <code>reasoning_efforts</code>：<code>none</code>、<code>low</code>…<code>xhigh</code> 等。</p><h3 id="context-window" tabindex="-1"><code>context_window</code> <a class="header-anchor" href="#context-window" aria-label="Permalink to &quot;`context_window`&quot;">​</a></h3><p>Memoh 用来：</p><ul><li>在网页上算当前会话占了多少上下文</li><li>驱动 <code>/status</code> 等</li><li>判断是否逼近上限</li><li>决定何时需要 <a href="./../../guides/compaction.html">会话上下文压缩</a></li></ul><p>不填也能用，但<strong>百分比</strong>会没法精确给。</p><h3 id="文生图模型" tabindex="-1">文生图模型 <a class="header-anchor" href="#文生图模型" aria-label="Permalink to &quot;文生图模型&quot;">​</a></h3><p>Bot 上可单挂 <strong>Image Generation Model</strong>，须是带 <code>image-output</code> 的 chat 模型。需要时与默认聊天模型分开。</p><hr><h2 id="embedding-模型" tabindex="-1">Embedding 模型 <a class="header-anchor" href="#embedding-模型" aria-label="Permalink to &quot;Embedding 模型&quot;">​</a></h2><p>Embedding 模型用于语义索引与检索。</p><p>必填字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Dimensions</strong></td><td>embedding 输出的向量维数，如 <code>1536</code>。</td></tr></tbody></table><p>配合记忆提供方，或任何依赖向量检索的能力使用。</p><hr><h2 id="语音合成与转写模型" tabindex="-1">语音合成与转写模型 <a class="header-anchor" href="#语音合成与转写模型" aria-label="Permalink to &quot;语音合成与转写模型&quot;">​</a></h2><p>语音合成在 <a href="./tts/edge.html">TTS 提供方</a> 配，不跟普通 chat 模型服务商混流。当前语音合成类别包括：</p><ul><li>Edge：<code>edge-speech</code></li><li>OpenAI 兼容：<code>openai-speech</code></li><li>OpenRouter：<code>openrouter-speech</code></li><li>ElevenLabs：<code>elevenlabs-speech</code></li><li>Deepgram：<code>deepgram-speech</code></li><li>MiniMax：<code>minimax-speech</code></li><li>火山引擎：<code>volcengine-speech</code></li><li>阿里云：<code>alibabacloud-speech</code></li><li>Microsoft：<code>microsoft-speech</code></li></ul><p>语音转写在 Transcription 设置页配。当前语音转写类别包括：</p><ul><li>OpenAI 兼容：<code>openai-transcription</code></li><li>OpenRouter：<code>openrouter-transcription</code></li><li>ElevenLabs：<code>elevenlabs-transcription</code></li><li>Deepgram：<code>deepgram-transcription</code></li><li>Google：<code>google-transcription</code></li></ul><p>音频模型有 provider 专属的音色、格式、语速、音高、语言和识别设置，和 chat/embedding 不是一路设置。</p><hr><h2 id="怎么记省事" tabindex="-1">怎么记省事 <a class="header-anchor" href="#怎么记省事" aria-label="Permalink to &quot;怎么记省事&quot;">​</a></h2><p>对多数 Bot，可以分几条线想：</p><ul><li><strong>Chat</strong>：日常说人话</li><li><strong>Embedding</strong>：记忆</li><li><strong>Speech / Transcription / 生图模型</strong>：边能力</li></ul><p>不必强行一模型全包。</p><hr><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>给 Bot 绑聊天、生图、记忆、朗读等：<a href="./../../guides/working-with-bots.html">Bot</a></li><li>配语音提供方与语音模型：<a href="./tts/edge.html">TTS 提供方</a></li><li>配语音转文字：打开客户端的 Transcription 设置页</li></ul>',82)])])}const b=e(a,[["render",i]]);export{g as __pageData,b as default};
